"""CEGAR-style counterexample analysis, minimization, and refinement.

The Spacer layer (:mod:`spacer_verifier`) answers "is this transition system
safe?".  This module answers the follow-up questions that a real verifier has
to deal with when the answer is *no*:

* is the reported trace a genuine execution or an artefact of the abstraction
  (:class:`CEXValidator`),
* if it is an artefact, which predicates rule it out (:class:`PredicateRefiner`,
  via Craig interpolation),
* which predicates are worth keeping (:class:`AbstractDomain`),
* and, when the trace is genuine, what is the shortest trace that still
  reaches the error (:meth:`PredicateRefiner.minimize_cex`).

:class:`CEGARLoop` glues those pieces into the classic counterexample-guided
abstraction refinement loop.  Every iteration builds a *predicate abstraction*
of the concrete system -- a Boolean transition system whose state is the
valuation of the current predicates -- encodes it as the usual three Horn
clauses and hands it to Spacer::

    initA(B)                   -> Inv(B)
    Inv(B) /\\ transA(B, B')    -> Inv(B')
    Inv(B) /\\ ~safetyA(B)      -> Error

where, writing ``p_i`` for the predicates and ``X`` for the concrete state,

    initA(B)        = exists X.      init(X)  /\\ B  = p(X)
    transA(B, B')   = exists X, X'.  B = p(X) /\\ trans(X, X') /\\ B' = p(X')
    ~safetyA(B)     = exists X.      B = p(X) /\\ ~safety(X)

The concrete witnesses ``X``/``X'`` are free variables of the rule bodies, so
Horn semantics quantifies them existentially for us and Spacer computes the
abstract reachable states directly.  ``unsat`` proves the concrete system safe
(the abstraction over-approximates it); ``sat`` yields an abstract trace, which
is extracted from Spacer's ground refutation and then either concretised into a
real counterexample or refuted by interpolation.

Z3 no longer exposes its interpolation API, so :meth:`PredicateRefiner.interpolate`
implements model-based interpolation over a finite atom basis: models of the
prefix are generalised into cubes that are inconsistent with the suffix, and the
disjunction of those cubes is a Craig interpolant by construction.  The basis
holds the atoms of the program plus octagon atoms (``+-u +-v <= c``) read off the
sampled models, which is what lets the loop discover relational invariants such
as ``y - x <= 1``.
"""

import itertools
import time

import z3

from framework import report_result

__all__ = [
    "State",
    "Transition",
    "Counterexample",
    "ValidationResult",
    "CEXValidator",
    "AbstractDomain",
    "PredicateRefiner",
    "CEGARResult",
    "CEGARLoop",
    "CEGARSystem",
    "CEXMinimizerExperiment",
    "build_offbyone_counter",
    "build_double_counter",
    "build_array_bounds",
    "build_simple_loop",
    "build_producer_consumer",
    "SYSTEM_BUILDERS",
    "run_cegar_experiments",
]


# ---------------------------------------------------------------------------
# Small Z3 helpers
# ---------------------------------------------------------------------------

def _call(fn, args):
    """Call ``fn`` with ``args`` spread, tolerating callables that take a list."""
    try:
        return fn(*args)
    except TypeError:
        return fn(list(args))


def _as_expr(obj, args):
    """Return ``obj`` as a Z3 formula, applying it to ``args`` when callable."""
    if callable(obj) and not z3.is_expr(obj):
        return _call(obj, args)
    return obj


def _py_value(val):
    """Convert a Z3 model value into a plain Python value."""
    if val is None:
        return None
    if z3.is_int_value(val):
        return val.as_long()
    if z3.is_true(val):
        return True
    if z3.is_false(val):
        return False
    if z3.is_rational_value(val):
        return float(val.numerator_as_long()) / float(val.denominator_as_long())
    return val


def _z3_value(value, sort):
    """Convert a Python value back into a Z3 constant of ``sort``."""
    if z3.is_expr(value):
        return value
    if sort == z3.BoolSort():
        return z3.BoolVal(bool(value))
    if sort == z3.IntSort():
        return z3.IntVal(int(value))
    if sort == z3.RealSort():
        return z3.RealVal(value)
    return z3.Const(str(value), sort)


def _substitute(expr, src_vars, dst_vars):
    """Rename ``src_vars`` to ``dst_vars`` inside ``expr``."""
    pairs = [(s, d) for s, d in zip(src_vars, dst_vars) if s is not d]
    if not pairs:
        return expr
    return z3.substitute(expr, *pairs)


def _rename(prefix, variables):
    """Fresh copies of ``variables`` carrying ``prefix`` in their names."""
    return [z3.Const("%s%s" % (prefix, v.decl().name()), v.sort())
            for v in variables]


def _conj(parts):
    parts = [p for p in parts if p is not None]
    if not parts:
        return z3.BoolVal(True)
    if len(parts) == 1:
        return parts[0]
    return z3.And(*parts)


def _is_atom(expr):
    """True for formulas without Boolean structure (comparisons, predicates)."""
    if not z3.is_expr(expr) or expr.sort() != z3.BoolSort():
        return False
    if z3.is_quantifier(expr):
        return False
    if z3.is_true(expr) or z3.is_false(expr):
        return False
    if z3.is_and(expr) or z3.is_or(expr) or z3.is_not(expr) \
            or z3.is_implies(expr):
        return False
    if z3.is_app(expr) and expr.decl().kind() == z3.Z3_OP_ITE:
        return False
    return True


def collect_atoms(expr, out=None):
    """Collect the atomic sub-formulas of ``expr`` (deduplicated by text)."""
    if out is None:
        out = []
    if not z3.is_expr(expr):
        return out
    if _is_atom(expr):
        if all(str(a) != str(expr) for a in out):
            out.append(expr)
        return out
    if z3.is_quantifier(expr):
        return collect_atoms(expr.body(), out)
    if z3.is_app(expr):
        for i in range(expr.num_args()):
            collect_atoms(expr.arg(i), out)
    return out


def collect_vars(expr, out=None):
    """Collect the free constants (state variables) occurring in ``expr``."""
    if out is None:
        out = []
    seen = set(str(v) for v in out)

    def walk(e):
        if not z3.is_expr(e):
            return
        if z3.is_quantifier(e):
            walk(e.body())
            return
        if z3.is_const(e) and e.decl().kind() == z3.Z3_OP_UNINTERPRETED:
            if str(e) not in seen:
                seen.add(str(e))
                out.append(e)
            return
        if z3.is_app(e):
            for i in range(e.num_args()):
                walk(e.arg(i))

    walk(expr)
    return out


def _mentions_only(expr, variables):
    """True when every free constant of ``expr`` belongs to ``variables``."""
    allowed = set(str(v) for v in variables)
    used = [str(v) for v in collect_vars(expr)]
    return bool(used) and all(u in allowed for u in used)


# ---------------------------------------------------------------------------
# 1. Counterexample data structures
# ---------------------------------------------------------------------------

class State(object):
    """A concrete state: a mapping from variable name to concrete value."""

    def __init__(self, values):
        self.values = dict(values)

    def __getitem__(self, name):
        return self.values[name]

    def get(self, name, default=None):
        return self.values.get(name, default)

    def keys(self):
        return self.values.keys()

    def items(self):
        return self.values.items()

    def constraint(self, variables):
        """``And(v == value)`` for every ``v`` in ``variables`` known here."""
        parts = []
        for var in variables:
            name = var.decl().name()
            if name in self.values:
                parts.append(var == _z3_value(self.values[name], var.sort()))
        return _conj(parts)

    @classmethod
    def from_model(cls, model, variables, names=None):
        """Read the values of ``variables`` out of a Z3 ``model``.

        ``names`` optionally overrides the recorded variable names, which is how
        primed copies (``x_1``) are stored back under their base name (``x``).
        """
        names = names or [v.decl().name() for v in variables]
        values = {}
        for name, var in zip(names, variables):
            values[name] = _py_value(model.eval(var, model_completion=True))
        return cls(values)

    def __eq__(self, other):
        return isinstance(other, State) and self.values == other.values

    def __ne__(self, other):
        return not self.__eq__(other)

    def __hash__(self):
        return hash(tuple(sorted((k, str(v)) for k, v in self.values.items())))

    def __repr__(self):
        body = ", ".join("%s=%s" % (k, self.values[k])
                         for k in sorted(self.values))
        return "State(%s)" % body


class Transition(object):
    """A single step of a counterexample: ``src -- action --> dst``."""

    def __init__(self, src, dst, action="step"):
        self.src = src
        self.dst = dst
        self.action = action

    def __repr__(self):
        return "Transition(%r -%s-> %r)" % (self.src, self.action, self.dst)


class Counterexample(object):
    """A finite trace of :class:`Transition` objects."""

    def __init__(self, transitions):
        self.transitions = list(transitions)

    @property
    def length(self):
        """Number of transitions (a 0-length trace is a single bad state)."""
        return len(self.transitions)

    def __len__(self):
        return len(self.transitions)

    @property
    def states(self):
        """All visited states: every source plus the final destination."""
        if not self.transitions:
            return []
        return [t.src for t in self.transitions] + [self.transitions[-1].dst]

    @property
    def initial_state(self):
        return self.states[0] if self.transitions else None

    @property
    def final_state(self):
        return self.transitions[-1].dst if self.transitions else None

    def get_variable_trace(self, var_name):
        """The values taken by ``var_name`` in every visited state."""
        return [s.get(var_name) for s in self.states]

    @classmethod
    def from_states(cls, states, actions=None):
        """Build a trace from consecutive states."""
        states = list(states)
        if len(states) == 1:
            return cls([Transition(states[0], states[0], "stutter")])
        transitions = []
        for i in range(len(states) - 1):
            action = actions[i] if actions else "step"
            transitions.append(Transition(states[i], states[i + 1], action))
        return cls(transitions)

    def __repr__(self):
        return "Counterexample(length=%d, %s)" % (
            self.length, " -> ".join(repr(s) for s in self.states))


# ---------------------------------------------------------------------------
# 2. Counterexample validation
# ---------------------------------------------------------------------------

class ValidationResult(object):
    """Verdict of :meth:`CEXValidator.validate`."""

    def __init__(self, is_real, first_spurious_step=None, reason=None):
        self.is_real = is_real
        self.first_spurious_step = first_spurious_step
        self.reason = reason

    def __repr__(self):
        if self.is_real:
            return "ValidationResult(real)"
        return "ValidationResult(spurious, step=%s, reason=%s)" % (
            self.first_spurious_step, self.reason)


class CEXValidator(object):
    """Replay a counterexample concretely against the original system.

    A trace produced from an abstraction is only a *candidate*: consecutive
    abstract states need not be linked by a concrete transition.  Replaying the
    concrete values step by step decides whether the trace is real, and where it
    first breaks if it is not.
    """

    def __init__(self, state_vars, next_vars):
        self.state_vars = list(state_vars)
        self.next_vars = list(next_vars)

    def _sat(self, formula):
        solver = z3.Solver()
        solver.add(formula)
        return solver.check() == z3.sat

    def step_is_feasible(self, src, dst, trans_rel):
        """Is ``trans_rel`` satisfiable with ``src``/``dst`` plugged in?"""
        trans = _as_expr(trans_rel, self.state_vars + self.next_vars)
        return self._sat(z3.And(trans,
                                src.constraint(self.state_vars),
                                dst.constraint(self.next_vars)))

    def validate(self, cex, init_cond, trans_rel, safety):
        """Simulate ``cex`` concretely and report whether it is real.

        Returns a :class:`ValidationResult`.  ``first_spurious_step`` is the
        index of the first transition that cannot happen concretely, or ``-1``
        when the trace fails already in its initial state.
        """
        states = cex.states
        if not states:
            return ValidationResult(False, None, "empty trace")

        init = _as_expr(init_cond, self.state_vars)
        safe = _as_expr(safety, self.state_vars)

        # The trace has to start inside the initial condition.
        if not self._sat(z3.And(init, states[0].constraint(self.state_vars))):
            return ValidationResult(False, -1, "initial state violates init")

        # Every step has to be a concrete transition.
        for index, step in enumerate(cex.transitions):
            if not self.step_is_feasible(step.src, step.dst, trans_rel):
                return ValidationResult(False, index,
                                        "transition %d is infeasible" % index)

        # And the last state has to break the property.
        last = states[-1].constraint(self.state_vars)
        if not self._sat(z3.And(z3.Not(safe), last)):
            return ValidationResult(False, len(cex.transitions),
                                    "final state does not violate safety")

        return ValidationResult(True, None, "concrete trace reaches the error")


# ---------------------------------------------------------------------------
# 3. Predicate abstraction domain
# ---------------------------------------------------------------------------

class AbstractDomain(object):
    """The set of predicates the abstraction currently tracks.

    Predicates are formulas over ``state_vars``.  The abstract state of a
    concrete state is the vector of truth values of those predicates.
    """

    def __init__(self, state_vars, predicates=None, pinned=None):
        self.state_vars = list(state_vars)
        self._predicates = []
        self._pinned = set()
        for pred in (pinned or []):
            self.add_predicate(pred, pin=True)
        for pred in (predicates or []):
            self.add_predicate(pred)

    # -- inspection ---------------------------------------------------------

    @property
    def predicates(self):
        return list(self._predicates)

    @property
    def predicate_count(self):
        return len(self._predicates)

    def __len__(self):
        return len(self._predicates)

    def __iter__(self):
        return iter(self._predicates)

    def is_pinned(self, pred):
        return str(pred) in self._pinned

    # -- semantic tests -----------------------------------------------------

    @staticmethod
    def _valid(formula):
        solver = z3.Solver()
        solver.add(z3.Not(formula))
        return solver.check() == z3.unsat

    def is_subsumed(self, pred_new, pred_existing):
        """True when ``pred_existing`` implies ``pred_new``.

        A predicate implied by one we already track carries no extra
        information as a *conjunct*, which is how :meth:`add_predicate` and
        :meth:`PredicateRefiner.strengthen_invariant` use it.
        """
        return self._valid(z3.Implies(pred_existing, pred_new))

    def is_trivial(self, pred):
        """True for predicates that are valid or unsatisfiable."""
        solver = z3.Solver()
        solver.add(pred)
        if solver.check() == z3.unsat:
            return True
        return self._valid(pred)

    # -- mutation -----------------------------------------------------------

    def add_predicate(self, pred, pin=False):
        """Add ``pred`` unless it is trivial or already subsumed.

        Any *non-pinned* predicate that ``pred`` subsumes is dropped again.
        Predicates coming from the property under verification are pinned:
        they are implied by many refinement predicates, and removing them would
        coarsen the abstraction below the property itself and make the loop
        diverge.
        """
        pred = z3.simplify(pred)
        if not z3.is_expr(pred) or pred.sort() != z3.BoolSort():
            return False
        if self.is_trivial(pred):
            return False
        for existing in self._predicates:
            if str(existing) == str(pred):
                if pin:
                    self._pinned.add(str(existing))
                return False
            if self.is_subsumed(pred, existing):
                return False
        kept = []
        for existing in self._predicates:
            if not self.is_pinned(existing) and self.is_subsumed(existing, pred):
                continue
            kept.append(existing)
        kept.append(pred)
        self._predicates = kept
        if pin:
            self._pinned.add(str(pred))
        return True

    def extend(self, preds, pin=False):
        """Add several predicates, returning how many were actually kept."""
        return sum(1 for p in preds if self.add_predicate(p, pin=pin))

    # -- abstraction --------------------------------------------------------

    def abstract_state(self, concrete_state):
        """Evaluate every predicate on ``concrete_state``.

        ``concrete_state`` may be a :class:`State` or a plain ``dict``; the
        result is a tuple of booleans, one per predicate.
        """
        if not isinstance(concrete_state, State):
            concrete_state = State(concrete_state)
        binding = concrete_state.constraint(self.state_vars)
        out = []
        for pred in self._predicates:
            value = z3.simplify(z3.substitute(
                pred, *[(v, _z3_value(concrete_state[v.decl().name()], v.sort()))
                        for v in self.state_vars
                        if v.decl().name() in concrete_state.values]))
            if z3.is_true(value):
                out.append(True)
            elif z3.is_false(value):
                out.append(False)
            else:  # partially specified state: fall back to an SMT check
                solver = z3.Solver()
                solver.add(z3.And(binding, z3.Not(pred)))
                out.append(solver.check() == z3.unsat)
        return tuple(out)

    def cube(self, valuation, variables=None):
        """The concrete formula described by an abstract state."""
        variables = variables or self.state_vars
        parts = []
        for pred, value in zip(self._predicates, valuation):
            renamed = _substitute(pred, self.state_vars, variables)
            parts.append(renamed if value else z3.Not(renamed))
        return _conj(parts)


# ---------------------------------------------------------------------------
# 4. Interpolation-based predicate refinement
# ---------------------------------------------------------------------------

class PredicateRefiner(object):
    """Derives new predicates from an infeasible counterexample.

    The workhorse is :meth:`interpolate`, a model-based Craig interpolation
    procedure: it repeatedly samples a model of the prefix ``A``, turns it into
    a cube over the shared variables, weakens the cube as far as it stays
    inconsistent with the suffix ``B``, and blocks it.  When ``A`` is exhausted
    the disjunction of the collected cubes ``I`` satisfies ``A |= I`` and
    ``I /\\ B`` unsat, i.e. it is an interpolant.
    """

    def __init__(self, state_vars, next_vars, atom_basis=None, max_cubes=6,
                 use_octagons=True):
        self.state_vars = list(state_vars)
        self.next_vars = list(next_vars)
        self.atom_basis = list(atom_basis or [])
        self.max_cubes = max_cubes
        self.use_octagons = use_octagons

    # -- path construction --------------------------------------------------

    def _path_vars(self, steps):
        """Fresh copies ``X^0 .. X^steps`` of the state variables."""
        return [_rename("s%d_" % i, self.state_vars) for i in range(steps + 1)]

    def path_formula(self, cex, trans_rel, init_cond=None, safety=None,
                     cubes=None):
        """Unroll the trace into ``(parts, path_vars)``.

        ``parts[0]`` constrains the first state, ``parts[i]`` is the ``i``-th
        transition (plus the abstract cube of the state it reaches) and the last
        part demands the safety violation.  Without ``init_cond``/``safety`` the
        trace's own end states are used as anchors, which asks the question
        "can exactly this trace happen?".
        """
        steps = cex.length if isinstance(cex, Counterexample) else int(cex)
        path = self._path_vars(steps)
        states = cex.states if isinstance(cex, Counterexample) else []

        def cube_at(index, variables):
            if not cubes:
                return None
            return _substitute(cubes[index], self.state_vars, variables)

        head = []
        if init_cond is not None:
            head.append(_substitute(_as_expr(init_cond, self.state_vars),
                                    self.state_vars, path[0]))
        elif states:
            head.append(states[0].constraint(path[0]))
        head.append(cube_at(0, path[0]))
        parts = [_conj(head)]

        trans = _as_expr(trans_rel, self.state_vars + self.next_vars)
        for i in range(steps):
            step = z3.substitute(
                trans,
                *([(v, n) for v, n in zip(self.state_vars, path[i])] +
                  [(v, n) for v, n in zip(self.next_vars, path[i + 1])]))
            parts.append(_conj([step, cube_at(i + 1, path[i + 1])]))

        tail = []
        if safety is not None:
            tail.append(z3.Not(_substitute(_as_expr(safety, self.state_vars),
                                           self.state_vars, path[steps])))
        elif states:
            tail.append(states[steps].constraint(path[steps]))
        parts.append(_conj(tail))
        return parts, path

    def path_is_feasible(self, cex, trans_rel, init_cond=None, safety=None,
                         cubes=None):
        """Check whether some concrete run follows the given path.

        Returns ``(feasible, states)`` where ``states`` is the concrete trace
        read from the model when the path is feasible.
        """
        parts, path = self.path_formula(cex, trans_rel, init_cond, safety, cubes)
        solver = z3.Solver()
        solver.add(_conj(parts))
        if solver.check() != z3.sat:
            return False, None
        model = solver.model()
        names = [v.decl().name() for v in self.state_vars]
        return True, [State.from_model(model, step_vars, names)
                      for step_vars in path]

    # -- interpolation ------------------------------------------------------

    def _basis_for(self, formulas, shared_vars):
        """Atoms over ``shared_vars`` gathered from ``formulas`` and the basis."""
        atoms = []
        for formula in formulas:
            collect_atoms(formula, atoms)
        for atom in self.atom_basis:
            for variables in (shared_vars,):
                renamed = _substitute(atom, self.state_vars, variables)
                if all(str(renamed) != str(a) for a in atoms):
                    atoms.append(renamed)
        return [a for a in atoms if _mentions_only(a, shared_vars)]

    def _model_cube(self, model, shared_vars, atoms):
        """A cube over ``shared_vars`` satisfied by ``model``.

        Literals are ordered from most to least specific so that the greedy
        weakening below drops point values first and keeps relational facts.
        """
        numeric = [v for v in shared_vars
                   if v.sort() in (z3.IntSort(), z3.RealSort())]
        bounds, sums, diffs, syntactic = [], [], [], []

        for var in shared_vars:
            value = model.eval(var, model_completion=True)
            if var.sort() == z3.BoolSort():
                syntactic.append(var if z3.is_true(value) else z3.Not(var))
            elif var in numeric:
                bounds.append(var <= value)
                bounds.append(var >= value)

        if self.use_octagons:
            for left, right in itertools.combinations(numeric, 2):
                total = model.eval(left + right, model_completion=True)
                delta = model.eval(left - right, model_completion=True)
                sums.append(left + right <= total)
                sums.append(left + right >= total)
                diffs.append(left - right <= delta)
                diffs.append(left - right >= delta)

        for atom in atoms:
            if atom.sort() != z3.BoolSort():
                continue
            value = model.eval(atom, model_completion=True)
            if z3.is_true(value):
                syntactic.append(atom)
            elif z3.is_false(value):
                syntactic.append(z3.Not(atom))

        return bounds + sums + diffs + syntactic

    def _weaken(self, literals, suffix):
        """Drop literals while the cube stays inconsistent with ``suffix``."""
        solver = z3.Solver()
        solver.add(suffix)

        def blocked(lits):
            solver.push()
            solver.add(*lits) if lits else None
            result = solver.check()
            solver.pop()
            return result == z3.unsat

        if not blocked(literals):
            return None  # the atom basis cannot separate this model
        kept = list(literals)
        index = 0
        while index < len(kept):
            trial = kept[:index] + kept[index + 1:]
            if blocked(trial):
                kept = trial
            else:
                index += 1
        return kept

    def interpolate(self, prefix, suffix, shared_vars):
        """Craig interpolant of ``prefix`` and ``suffix`` over ``shared_vars``.

        Returns a formula ``I`` with ``prefix |= I`` and ``I /\\ suffix``
        unsatisfiable, or ``None`` when ``prefix /\\ suffix`` is satisfiable or
        the atom basis is too weak to separate them.
        """
        joint = z3.Solver()
        joint.add(prefix, suffix)
        if joint.check() != z3.unsat:
            return None

        atoms = self._basis_for([prefix, suffix], shared_vars)
        sampler = z3.Solver()
        sampler.add(prefix)
        cubes = []
        for _ in range(self.max_cubes):
            if sampler.check() != z3.sat:
                if not cubes:
                    return z3.BoolVal(False)
                return z3.simplify(z3.Or(*cubes) if len(cubes) > 1 else cubes[0])
            literals = self._model_cube(sampler.model(), shared_vars, atoms)
            kept = self._weaken(literals, suffix)
            if kept is None:
                return None
            cube = _conj(kept)
            cubes.append(cube)
            sampler.add(z3.Not(cube))
        return None

    def extract_interpolants(self, cex, trans_rel, init_cond=None, safety=None,
                             cubes=None):
        """Interpolate between consecutive steps of an infeasible trace.

        For every cut point ``j`` the path is split into the prefix (steps
        ``0..j``) and the suffix (steps ``j+1..n`` together with the safety
        violation).  ``prefix /\\ ~suffix`` unsatisfiable means the trace cannot
        pass through step ``j``, and the interpolant -- a formula over the state
        at step ``j`` only -- is renamed back onto the state variables and
        returned as a new predicate.
        """
        parts, path = self.path_formula(cex, trans_rel, init_cond, safety, cubes)
        interpolants = []
        for cut in range(1, len(parts) - 1):
            prefix = _conj(parts[:cut + 1])
            suffix = _conj(parts[cut + 1:])
            interpolant = self.interpolate(prefix, suffix, path[cut])
            if interpolant is None:
                continue
            interpolant = _substitute(interpolant, path[cut], self.state_vars)
            if z3.is_true(interpolant) or z3.is_false(interpolant):
                continue
            interpolants.append(z3.simplify(interpolant))
        return interpolants

    @staticmethod
    def split_predicates(formula):
        """Break a formula into the atoms a predicate abstraction can track."""
        out = []
        for atom in collect_atoms(formula):
            if all(str(atom) != str(o) for o in out):
                out.append(atom)
        if not out and z3.is_expr(formula):
            out.append(formula)
        return out

    def strengthen_invariant(self, current_preds, new_interpolants):
        """Merge interpolants into a predicate set, dropping subsumed ones.

        The result is ordered ``current_preds`` first; a new predicate is only
        kept when no predicate already in the set implies it, and predicates it
        implies are removed (the conjunction of the set is unchanged by both
        rules).
        """
        domain = AbstractDomain(self.state_vars)
        for pred in current_preds:
            domain.add_predicate(pred, pin=True)
        for interpolant in new_interpolants:
            for pred in self.split_predicates(interpolant):
                domain.add_predicate(pred)
        return domain.predicates

    # -- minimization -------------------------------------------------------

    def minimize_cex(self, cex, trans_rel):
        """Shorten a trace by jumping over intermediate states.

        Whenever ``trans_rel`` admits a direct step from state ``i`` to a later
        state ``j``, everything in between is redundant: the shortened trace
        starts in the same state, ends in the same (error) state and uses only
        real transitions.  Longer jumps are tried first, and the scan is
        repeated until no jump is left.
        """
        if cex is None or cex.length <= 1:
            return cex
        validator = CEXValidator(self.state_vars, self.next_vars)
        states = list(cex.states)
        actions = [t.action for t in cex.transitions]

        index = 0
        while index < len(states) - 2:
            jumped = False
            for target in range(len(states) - 1, index + 1, -1):
                if validator.step_is_feasible(states[index], states[target],
                                              trans_rel):
                    states = states[:index + 1] + states[target:]
                    actions = (actions[:index] + ["jump"] + actions[target:])
                    jumped = True
                    break
            if not jumped:
                index += 1
        return Counterexample.from_states(states, actions)


# ---------------------------------------------------------------------------
# 5. The CEGAR loop
# ---------------------------------------------------------------------------

class CEGARResult(object):
    """Outcome of :meth:`CEGARLoop.run`."""

    def __init__(self, safe, iterations, predicates, cex=None, status=None,
                 original_cex=None, interpolants=None, predicates_added=0,
                 validations=None, elapsed=0.0, name=None):
        self.safe = safe
        self.iterations = iterations
        self.predicates = list(predicates or [])
        self.cex = cex
        self.status = status or ("safe" if safe else "unsafe")
        self.original_cex = original_cex
        self.interpolants = list(interpolants or [])
        self.predicates_added = predicates_added
        self.validations = list(validations or [])
        self.elapsed = elapsed
        self.name = name

    @property
    def predicate_count(self):
        return len(self.predicates)

    @property
    def cex_length(self):
        return self.cex.length if self.cex is not None else 0

    @property
    def original_cex_length(self):
        cex = self.original_cex if self.original_cex is not None else self.cex
        return cex.length if cex is not None else 0

    def __repr__(self):
        return ("CEGARResult(name=%s, safe=%s, status=%s, iterations=%d, "
                "predicates=%d, cex_length=%s)" % (
                    self.name, self.safe, self.status, self.iterations,
                    len(self.predicates), self.cex_length))


class CEGARLoop(object):
    """Counterexample-guided abstraction refinement over a transition system.

    ``init_cond``, ``trans_rel`` and ``safety`` are either Z3 formulas over
    ``state_vars``/``next_vars`` or callables that build them from those
    variables.  When the variables are not given explicitly they are inferred:
    the constants of ``init_cond`` and ``safety`` are the state variables and
    the remaining constants of ``trans_rel`` are their primed copies (matched by
    the ``_next``/``'``/``p`` naming conventions used across this repository).
    """

    NEXT_SUFFIXES = ("_next", "_p", "'", "p", "n", "!1", "_1")

    def __init__(self, init_cond, trans_rel, safety, max_iterations=20,
                 predicate_budget=50, state_vars=None, next_vars=None,
                 name="system", seed_predicates=None, max_trace_depth=12,
                 timeout_ms=None):
        self.name = name
        self.max_iterations = max_iterations
        self.predicate_budget = predicate_budget
        self.max_trace_depth = max_trace_depth
        self.timeout_ms = timeout_ms

        state_vars, next_vars = self._infer_variables(
            init_cond, trans_rel, safety, state_vars, next_vars)
        self.state_vars = state_vars
        self.next_vars = next_vars

        self.init_cond = _as_expr(init_cond, state_vars)
        self.trans_rel = _as_expr(trans_rel, state_vars + next_vars)
        self.safety = _as_expr(safety, state_vars)

        atom_basis = self._program_atoms()
        self.refiner = PredicateRefiner(state_vars, next_vars,
                                        atom_basis=atom_basis)
        self.validator = CEXValidator(state_vars, next_vars)

        # The property atoms are seeded (and pinned) first so that the very
        # first abstraction can already talk about the safety property.
        self.domain = AbstractDomain(state_vars)
        seeds = list(seed_predicates) if seed_predicates is not None else (
            collect_atoms(self.safety) + collect_atoms(self.init_cond))
        self.seed_predicates = seeds
        self.domain.extend(seeds, pin=True)

        self.iterations = 0
        self.predicates_added = 0
        self.interpolants = []
        self.validations = []
        self.traces = []

    # -- setup --------------------------------------------------------------

    def _infer_variables(self, init_cond, trans_rel, safety, state_vars,
                         next_vars):
        if state_vars is not None and next_vars is not None:
            return list(state_vars), list(next_vars)
        if state_vars is None:
            if callable(init_cond) and not z3.is_expr(init_cond):
                raise ValueError("state_vars is required for callable systems")
            state_vars = collect_vars(init_cond)
            collect_vars(_as_expr(safety, state_vars), state_vars)
        state_vars = list(state_vars)
        if next_vars is None:
            trans = _as_expr(trans_rel, state_vars)
            known = set(str(v) for v in state_vars)
            leftovers = [v for v in collect_vars(trans) if str(v) not in known]
            next_vars = []
            for var in state_vars:
                base = var.decl().name()
                match = None
                for candidate in leftovers:
                    name = candidate.decl().name()
                    if any(name == base + suffix for suffix in self.NEXT_SUFFIXES):
                        match = candidate
                        break
                if match is None:
                    match = z3.Const(base + "_next", var.sort())
                next_vars.append(match)
        return state_vars, list(next_vars)

    def _program_atoms(self):
        """Atoms of the program, expressed over the unprimed state variables."""
        atoms = collect_atoms(self.init_cond)
        collect_atoms(self.safety, atoms)
        for atom in collect_atoms(self.trans_rel):
            unprimed = _substitute(atom, self.next_vars, self.state_vars)
            if all(str(unprimed) != str(a) for a in atoms):
                atoms.append(unprimed)
        return [a for a in atoms if _mentions_only(a, self.state_vars)]

    # -- abstraction --------------------------------------------------------

    def _link(self, bits, variables):
        """``b_i <-> p_i(variables)`` for every tracked predicate."""
        predicates = self.domain.predicates
        parts = [bits[i] == _substitute(predicates[i], self.state_vars, variables)
                 for i in range(len(predicates))]
        return _conj(parts)

    def abstract_query(self):
        """Ask Spacer whether the current abstraction can reach the error.

        Returns ``(result, abstract_trace)``; the trace is the list of abstract
        states (tuples of booleans) extracted from Spacer's ground refutation.
        """
        predicates = self.domain.predicates
        arity = len(predicates)
        fp = z3.Fixedpoint()
        fp.set(engine="spacer")
        if self.timeout_ms:
            fp.set(timeout=int(self.timeout_ms))

        inv = z3.Function("Inv", *([z3.BoolSort()] * arity + [z3.BoolSort()]))
        error = z3.Function("Error_%s" % self.name.replace(" ", "_"),
                            z3.BoolSort())
        fp.register_relation(inv, error)

        bits = [z3.Bool("b%d" % i) for i in range(arity)]
        next_bits = [z3.Bool("b%d_next" % i) for i in range(arity)]
        fp.declare_var(*(bits + next_bits + self.state_vars + self.next_vars))

        fp.rule(inv(*bits), [self.init_cond, self._link(bits, self.state_vars)],
                "init")
        fp.rule(inv(*next_bits),
                [inv(*bits), self._link(bits, self.state_vars), self.trans_rel,
                 self._link(next_bits, self.next_vars)], "step")
        fp.rule(error(), [inv(*bits), self._link(bits, self.state_vars),
                          z3.Not(self.safety)], "error")

        result = fp.query(error())
        trace = None
        if result == z3.sat:
            try:
                trace = self._extract_abstract_trace(fp.get_answer(), arity)
            except z3.Z3Exception:  # pragma: no cover - defensive
                trace = None
        return result, trace

    @staticmethod
    def _extract_abstract_trace(answer, arity):
        """Read the ground ``Inv(...)`` facts out of a Spacer refutation.

        Spacer answers a ``sat`` query with a hyper-resolution proof whose
        intermediate conclusions are the ground facts of the derivation, i.e.
        exactly the abstract states along the counterexample.  They appear
        outermost-first, so the collected list is reversed.
        """
        facts = []

        def walk(expr):
            if not z3.is_app(expr):
                return
            if expr.num_args():
                conclusion = expr.arg(expr.num_args() - 1)
                if z3.is_app(conclusion) and conclusion.decl().name() == "Inv":
                    valuation = tuple(z3.is_true(conclusion.arg(i))
                                      for i in range(conclusion.num_args()))
                    if all(z3.is_true(conclusion.arg(i)) or
                           z3.is_false(conclusion.arg(i))
                           for i in range(conclusion.num_args())):
                        facts.append(valuation)
            for i in range(expr.num_args()):
                walk(expr.arg(i))

        walk(answer)
        if not facts and arity == 0:
            return [()]
        seen_last = None
        ordered = []
        for fact in reversed(facts):
            ordered.append(fact)
            seen_last = fact
        del seen_last
        return ordered

    def _concretize(self, abstract_trace):
        """Pick one concrete witness per abstract state of the trace.

        Each witness satisfies the predicates of its abstract state (and the
        initial condition / safety violation at the ends), but consecutive
        witnesses are chosen independently -- which is precisely why the result
        is only a *candidate* counterexample that has to be validated.
        """
        states = []
        last = len(abstract_trace) - 1
        for index, valuation in enumerate(abstract_trace):
            solver = z3.Solver()
            solver.add(self.domain.cube(valuation))
            if index == 0:
                solver.add(self.init_cond)
            if index == last:
                solver.add(z3.Not(self.safety))
            if solver.check() != z3.sat:
                solver = z3.Solver()
                solver.add(self.domain.cube(valuation))
                if solver.check() != z3.sat:
                    return None
            states.append(State.from_model(solver.model(), self.state_vars))
        return Counterexample.from_states(states)

    # -- main loop ----------------------------------------------------------

    def run(self):
        """Run the CEGAR loop and return a :class:`CEGARResult`."""
        started = time.time()
        status = "max_iterations"
        while self.iterations < self.max_iterations:
            self.iterations += 1
            result, abstract_trace = self.abstract_query()

            if result == z3.unsat:
                return self._result(True, "safe", started)
            if result != z3.sat:
                status = "unknown"
                break
            if not abstract_trace:
                status = "no_trace"
                break

            self.traces.append(abstract_trace)
            cubes = [self.domain.cube(v) for v in abstract_trace]
            candidate = self._concretize(abstract_trace)
            if candidate is None:  # pragma: no cover - defensive
                status = "no_trace"
                break

            verdict = self.validator.validate(candidate, self.init_cond,
                                              self.trans_rel, self.safety)
            self.validations.append(verdict)
            if verdict.is_real:
                return self._unsafe(candidate, started)

            # The candidate is spurious; is *any* run along this abstract path
            # concrete?  If so the system really is unsafe.
            feasible, concrete = self.refiner.path_is_feasible(
                candidate, self.trans_rel, self.init_cond, self.safety, cubes)
            if feasible:
                return self._unsafe(Counterexample.from_states(concrete), started)

            interpolants = self.refiner.extract_interpolants(
                candidate, self.trans_rel, self.init_cond, self.safety, cubes)
            self.interpolants.extend(interpolants)
            added = 0
            for interpolant in interpolants:
                for pred in self.refiner.split_predicates(interpolant):
                    if self.domain.add_predicate(pred):
                        added += 1
            if added == 0:
                status = "no_refinement"
                break
            self.predicates_added += added
            if self.domain.predicate_count > self.predicate_budget:
                status = "predicate_budget_exceeded"
                break

        return self._result(False, status, started)

    def _unsafe(self, cex, started):
        minimized = self.refiner.minimize_cex(cex, self.trans_rel)
        return self._result(False, "unsafe", started, cex=minimized,
                            original_cex=cex)

    def _result(self, safe, status, started, cex=None, original_cex=None):
        return CEGARResult(
            safe=safe,
            iterations=self.iterations,
            predicates=self.domain.predicates,
            cex=cex,
            status=status,
            original_cex=original_cex,
            interpolants=self.interpolants,
            predicates_added=self.predicates_added,
            validations=self.validations,
            elapsed=time.time() - started,
            name=self.name,
        )


# ---------------------------------------------------------------------------
# 6. Benchmark systems and the experiment driver
# ---------------------------------------------------------------------------

class CEGARSystem(object):
    """A named transition system together with its expected CEGAR verdict."""

    def __init__(self, name, state_vars, next_vars, init, trans, safety,
                 description="", expected_safe=None):
        self.name = name
        self.state_vars = list(state_vars)
        self.next_vars = list(next_vars)
        self.init = init
        self.trans = trans
        self.safety = safety
        self.description = description
        self.expected_safe = expected_safe

    def loop(self, **kwargs):
        kwargs.setdefault("name", self.name)
        return CEGARLoop(self.init, self.trans, self.safety,
                         state_vars=self.state_vars,
                         next_vars=self.next_vars, **kwargs)

    def __repr__(self):
        return "CEGARSystem(%s)" % self.name


def _vars(names):
    """``(state_vars, next_vars)`` integer variables for ``names``."""
    state = [z3.Int(n) for n in names]
    nxt = [z3.Int(n + "_next") for n in names]
    return state, nxt


def build_offbyone_counter(bound=10):
    """Counter whose companion variable trails it by one.

    ``y`` is always ``x + 1``, so with ``x <= bound`` the bound ``y <= bound+1``
    holds -- but neither conjunct is inductive on its own, so the abstraction
    has to discover the relational invariant ``y - x <= 1`` first.
    """
    state, nxt = _vars(["x", "y"])
    x, y = state
    xn, yn = nxt
    init = z3.And(x == 0, y == 1)
    trans = z3.Or(z3.And(x < bound, xn == x + 1, yn == y + 1),
                  z3.And(x >= bound, xn == x, yn == y))
    safety = y <= bound + 1
    return CEGARSystem("offbyone_counter", state, nxt, init, trans, safety,
                       "counter with an off-by-one companion variable",
                       expected_safe=True)


def build_double_counter(limit=6):
    """``x += 1`` / ``y += 2`` each step; ``x + y <= limit`` really is violated."""
    state, nxt = _vars(["x", "y"])
    x, y = state
    xn, yn = nxt
    init = z3.And(x == 0, y == 0)
    trans = z3.And(xn == x + 1, yn == y + 2)
    safety = x + y <= limit
    return CEGARSystem("double_counter", state, nxt, init, trans, safety,
                       "double counter that overruns its budget",
                       expected_safe=False)


def build_array_bounds(size=8):
    """Index/length/counter walk of an array; the index stays in bounds.

    Three separate facts are needed -- ``len`` never changes, ``idx <= len`` and
    ``cnt`` follows ``idx`` -- so the abstraction is refined several times.
    """
    state, nxt = _vars(["idx", "cnt", "len"])
    idx, cnt, length = state
    idxn, cntn, lengthn = nxt
    init = z3.And(idx == 0, cnt == 0, length == size)
    step = z3.And(idx < length, idxn == idx + 1, cntn == cnt + 1,
                  lengthn == length)
    done = z3.And(idx >= length, idxn == idx, cntn == cnt, lengthn == length)
    trans = z3.Or(step, done)
    safety = z3.And(idx >= 0, idx <= length, cnt <= size)
    return CEGARSystem("array_bounds", state, nxt, init, trans, safety,
                       "array index/counter stays inside the array",
                       expected_safe=True)


def build_simple_loop():
    """``x := x + 1`` from zero; ``x >= 0`` is inductive, so no refinement."""
    state, nxt = _vars(["x"])
    x = state[0]
    xn = nxt[0]
    init = x == 0
    trans = xn == x + 1
    safety = x >= 0
    return CEGARSystem("simple_loop", state, nxt, init, trans, safety,
                       "increment loop with the inductive invariant x >= 0",
                       expected_safe=True)


def build_producer_consumer(capacity=3):
    """Producer/consumer over a bounded buffer that can overflow.

    ``produce``, ``consume`` and ``idle`` are all enabled, so the error is
    reachable by many traces of different lengths -- the ones with idle or
    produce/consume detours are exactly what :meth:`minimize_cex` removes.
    """
    state, nxt = _vars(["buf", "prod", "cons"])
    buf, prod, cons = state
    bufn, prodn, consn = nxt
    init = z3.And(buf == 0, prod == 0, cons == 0)
    produce = z3.And(bufn == buf + 1, prodn == prod + 1, consn == cons)
    consume = z3.And(buf > 0, bufn == buf - 1, consn == cons + 1, prodn == prod)
    idle = z3.And(bufn == buf, prodn == prod, consn == cons)
    trans = z3.Or(produce, consume, idle)
    safety = buf <= capacity
    return CEGARSystem("producer_consumer", state, nxt, init, trans, safety,
                       "bounded buffer that overflows its capacity",
                       expected_safe=False)


SYSTEM_BUILDERS = [
    build_offbyone_counter,
    build_double_counter,
    build_array_bounds,
    build_simple_loop,
    build_producer_consumer,
]

METRICS = [
    "CEGAR_ITERATIONS",
    "CEGAR_PREDICATES_ADDED",
    "CEGAR_CEX_LENGTH_ORIGINAL",
    "CEGAR_CEX_LENGTH_MINIMIZED",
    "CEGAR_VERIFIED_SAFE",
]


class CEXMinimizerExperiment(object):
    """Run the CEGAR loop over the benchmark systems and collect the metrics."""

    def __init__(self, systems=None, max_iterations=20, predicate_budget=50):
        self.systems = list(systems) if systems is not None else [
            builder() for builder in SYSTEM_BUILDERS]
        self.max_iterations = max_iterations
        self.predicate_budget = predicate_budget
        self.results = []

    def run(self):
        """Verify every system, returning the metric dictionary."""
        self.results = []
        for system in self.systems:
            loop = system.loop(max_iterations=self.max_iterations,
                               predicate_budget=self.predicate_budget)
            self.results.append(loop.run())
        return self.metrics()

    def metrics(self):
        unsafe = [r for r in self.results if r.cex is not None]
        metrics = {
            "CEGAR_ITERATIONS": sum(r.iterations for r in self.results),
            "CEGAR_PREDICATES_ADDED": sum(r.predicates_added
                                          for r in self.results),
            "CEGAR_CEX_LENGTH_ORIGINAL": sum(r.original_cex_length
                                             for r in unsafe),
            "CEGAR_CEX_LENGTH_MINIMIZED": sum(r.cex_length for r in unsafe),
            "CEGAR_VERIFIED_SAFE": sum(1 for r in self.results if r.safe),
        }
        return metrics

    def summary(self):
        """Human-readable per-system report (used by the tests and CLI)."""
        lines = []
        for result in self.results:
            lines.append("%-20s %-8s iterations=%2d predicates=%2d "
                         "cex=%s->%s" % (
                             result.name, result.status, result.iterations,
                             len(result.predicates),
                             result.original_cex_length, result.cex_length))
        return "\n".join(lines)


def run_cegar_experiments(systems=None):
    """Run the CEGAR experiments and report the five ``KEY: VALUE`` metrics."""
    experiment = CEXMinimizerExperiment(systems=systems)
    metrics = experiment.run()
    for key in METRICS:
        report_result(key, metrics[key])
    return metrics


if __name__ == "__main__":
    experiment = CEXMinimizerExperiment()
    results = experiment.run()
    print(experiment.summary())
    for metric in METRICS:
        report_result(metric, results[metric])

toolUseResult.content:
"""CEGAR-style counterexample analysis, minimization, and refinement.

The Spacer layer (:mod:`spacer_verifier`) answers "is this transition system
safe?".  This module answers the follow-up questions that a real verifier has
to deal with when the answer is *no*:

* is the reported trace a genuine execution or an artefact of the abstraction
  (:class:`CEXValidator`),
* if it is an artefact, which predicates rule it out (:class:`PredicateRefiner`,
  via Craig interpolation),
* which predicates are worth keeping (:class:`AbstractDomain`),
* and, when the trace is genuine, what is the shortest trace that still
  reaches the error (:meth:`PredicateRefiner.minimize_cex`).

:class:`CEGARLoop` glues those pieces into the classic counterexample-guided
abstraction refinement loop.  Every iteration builds a *predicate abstraction*
of the concrete system -- a Boolean transition system whose state is the
valuation of the current predicates -- encodes it as the usual three Horn
clauses and hands it to Spacer::

    initA(B)                   -> Inv(B)
    Inv(B) /\\ transA(B, B')    -> Inv(B')
    Inv(B) /\\ ~safetyA(B)      -> Error

where, writing ``p_i`` for the predicates and ``X`` for the concrete state,

    initA(B)        = exists X.      init(X)  /\\ B  = p(X)
    transA(B, B')   = exists X, X'.  B = p(X) /\\ trans(X, X') /\\ B' = p(X')
    ~safetyA(B)     = exists X.      B = p(X) /\\ ~safety(X)

The concrete witnesses ``X``/``X'`` are free variables of the rule bodies, so
Horn semantics quantifies them existentially for us and Spacer computes the
abstract reachable states directly.  ``unsat`` proves the concrete system safe
(the abstraction over-approximates it); ``sat`` yields an abstract trace, which
is extracted from Spacer's ground refutation and then either concretised into a
real counterexample or refuted by interpolation.

Z3 no longer exposes its interpolation API, so :meth:`PredicateRefiner.interpolate`
implements model-based interpolation over a finite atom basis: models of the
prefix are generalised into cubes that are inconsistent with the suffix, and the
disjunction of those cubes is a Craig interpolant by construction.  The basis
holds the atoms of the program plus octagon atoms (``+-u +-v <= c``) read off the
sampled models, which is what lets the loop discover relational invariants such
as ``y - x <= 1``.
"""

import itertools
import time

import z3

from framework import report_result

__all__ = [
    "State",
    "Transition",
    "Counterexample",
    "ValidationResult",
    "CEXValidator",
    "AbstractDomain",
    "PredicateRefiner",
    "CEGARResult",
    "CEGARLoop",
    "CEGARSystem",
    "CEXMinimizerExperiment",
    "build_offbyone_counter",
    "build_double_counter",
    "build_array_bounds",
    "build_simple_loop",
    "build_producer_consumer",
    "SYSTEM_BUILDERS",
    "run_cegar_experiments",
]


# ---------------------------------------------------------------------------
# Small Z3 helpers
# ---------------------------------------------------------------------------

def _call(fn, args):
    """Call ``fn`` with ``args`` spread, tolerating callables that take a list."""
    try:
        return fn(*args)
    except TypeError:
        return fn(list(args))


def _as_expr(obj, args):
    """Return ``obj`` as a Z3 formula, applying it to ``args`` when callable."""
    if callable(obj) and not z3.is_expr(obj):
        return _call(obj, args)
    return obj


def _py_value(val):
    """Convert a Z3 model value into a plain Python value."""
    if val is None:
        return None
    if z3.is_int_value(val):
        return val.as_long()
    if z3.is_true(val):
        return True
    if z3.is_false(val):
        return False
    if z3.is_rational_value(val):
        return float(val.numerator_as_long()) / float(val.denominator_as_long())
    return val


def _z3_value(value, sort):
    """Convert a Python value back into a Z3 constant of ``sort``."""
    if z3.is_expr(value):
        return value
    if sort == z3.BoolSort():
        return z3.BoolVal(bool(value))
    if sort == z3.IntSort():
        return z3.IntVal(int(value))
    if sort == z3.RealSort():
        return z3.RealVal(value)
    return z3.Const(str(value), sort)


def _substitute(expr, src_vars, dst_vars):
    """Rename ``src_vars`` to ``dst_vars`` inside ``expr``."""
    pairs = [(s, d) for s, d in zip(src_vars, dst_vars) if s is not d]
    if not pairs:
        return expr
    return z3.substitute(expr, *pairs)


def _rename(prefix, variables):
    """Fresh copies of ``variables`` carrying ``prefix`` in their names."""
    return [z3.Const("%s%s" % (prefix, v.decl().name()), v.sort())
            for v in variables]


def _conj(parts):
    parts = [p for p in parts if p is not None]
    if not parts:
        return z3.BoolVal(True)
    if len(parts) == 1:
        return parts[0]
    return z3.And(*parts)


def _is_atom(expr):
    """True for formulas without Boolean structure (comparisons, predicates)."""
    if not z3.is_expr(expr) or expr.sort() != z3.BoolSort():
        return False
    if z3.is_quantifier(expr):
        return False
    if z3.is_true(expr) or z3.is_false(expr):
        return False
    if z3.is_and(expr) or z3.is_or(expr) or z3.is_not(expr) \
            or z3.is_implies(expr):
        return False
    if z3.is_app(expr) and expr.decl().kind() == z3.Z3_OP_ITE:
        return False
    return True


def collect_atoms(expr, out=None):
    """Collect the atomic sub-formulas of ``expr`` (deduplicated by text)."""
    if out is None:
        out = []
    if not z3.is_expr(expr):
        return out
    if _is_atom(expr):
        if all(str(a) != str(expr) for a in out):
            out.append(expr)
        return out
    if z3.is_quantifier(expr):
        return collect_atoms(expr.body(), out)
    if z3.is_app(expr):
        for i in range(expr.num_args()):
            collect_atoms(expr.arg(i), out)
    return out


def collect_vars(expr, out=None):
    """Collect the free constants (state variables) occurring in ``expr``."""
    if out is None:
        out = []
    seen = set(str(v) for v in out)

    def walk(e):
        if not z3.is_expr(e):
            return
        if z3.is_quantifier(e):
            walk(e.body())
            return
        if z3.is_const(e) and e.decl().kind() == z3.Z3_OP_UNINTERPRETED:
            if str(e) not in seen:
                seen.add(str(e))
                out.append(e)
            return
        if z3.is_app(e):
            for i in range(e.num_args()):
                walk(e.arg(i))

    walk(expr)
    return out


def _mentions_only(expr, variables):
    """True when every free constant of ``expr`` belongs to ``variables``."""
    allowed = set(str(v) for v in variables)
    used = [str(v) for v in collect_vars(expr)]
    return bool(used) and all(u in allowed for u in used)


# ---------------------------------------------------------------------------
# 1. Counterexample data structures
# ---------------------------------------------------------------------------

class State(object):
    """A concrete state: a mapping from variable name to concrete value."""

    def __init__(self, values):
        self.values = dict(values)

    def __getitem__(self, name):
        return self.values[name]

    def get(self, name, default=None):
        return self.values.get(name, default)

    def keys(self):
        return self.values.keys()

    def items(self):
        return self.values.items()

    def constraint(self, variables):
        """``And(v == value)`` for every ``v`` in ``variables`` known here."""
        parts = []
        for var in variables:
            name = var.decl().name()
            if name in self.values:
                parts.append(var == _z3_value(self.values[name], var.sort()))
        return _conj(parts)

    @classmethod
    def from_model(cls, model, variables, names=None):
        """Read the values of ``variables`` out of a Z3 ``model``.

        ``names`` optionally overrides the recorded variable names, which is how
        primed copies (``x_1``) are stored back under their base name (``x``).
        """
        names = names or [v.decl().name() for v in variables]
        values = {}
        for name, var in zip(names, variables):
            values[name] = _py_value(model.eval(var, model_completion=True))
        return cls(values)

    def __eq__(self, other):
        return isinstance(other, State) and self.values == other.values

    def __ne__(self, other):
        return not self.__eq__(other)

    def __hash__(self):
        return hash(tuple(sorted((k, str(v)) for k, v in self.values.items())))

    def __repr__(self):
        body = ", ".join("%s=%s" % (k, self.values[k])
                         for k in sorted(self.values))
        return "State(%s)" % body


class Transition(object):
    """A single step of a counterexample: ``src -- action --> dst``."""

    def __init__(self, src, dst, action="step"):
        self.src = src
        self.dst = dst
        self.action = action

    def __repr__(self):
        return "Transition(%r -%s-> %r)" % (self.src, self.action, self.dst)


class Counterexample(object):
    """A finite trace of :class:`Transition` objects."""

    def __init__(self, transitions):
        self.transitions = list(transitions)

    @property
    def length(self):
        """Number of transitions (a 0-length trace is a single bad state)."""
        return len(self.transitions)

    def __len__(self):
        return len(self.transitions)

    @property
    def states(self):
        """All visited states: every source plus the final destination."""
        if not self.transitions:
            return []
        return [t.src for t in self.transitions] + [self.transitions[-1].dst]

    @property
    def initial_state(self):
        return self.states[0] if self.transitions else None

    @property
    def final_state(self):
        return self.transitions[-1].dst if self.transitions else None

    def get_variable_trace(self, var_name):
        """The values taken by ``var_name`` in every visited state."""
        return [s.get(var_name) for s in self.states]

    @classmethod
    def from_states(cls, states, actions=None):
        """Build a trace from consecutive states."""
        states = list(states)
        if len(states) == 1:
            return cls([Transition(states[0], states[0], "stutter")])
        transitions = []
        for i in range(len(states) - 1):
            action = actions[i] if actions else "step"
            transitions.append(Transition(states[i], states[i + 1], action))
        return cls(transitions)

    def __repr__(self):
        return "Counterexample(length=%d, %s)" % (
            self.length, " -> ".join(repr(s) for s in self.states))


# ---------------------------------------------------------------------------
# 2. Counterexample validation
# ---------------------------------------------------------------------------

class ValidationResult(object):
    """Verdict of :meth:`CEXValidator.validate`."""

    def __init__(self, is_real, first_spurious_step=None, reason=None):
        self.is_real = is_real
        self.first_spurious_step = first_spurious_step
        self.reason = reason

    def __repr__(self):
        if self.is_real:
            return "ValidationResult(real)"
        return "ValidationResult(spurious, step=%s, reason=%s)" % (
            self.first_spurious_step, self.reason)


class CEXValidator(object):
    """Replay a counterexample concretely against the original system.

    A trace produced from an abstraction is only a *candidate*: consecutive
    abstract states need not be linked by a concrete transition.  Replaying the
    concrete values step by step decides whether the trace is real, and where it
    first breaks if it is not.
    """

    def __init__(self, state_vars, next_vars):
        self.state_vars = list(state_vars)
        self.next_vars = list(next_vars)

    def _sat(self, formula):
        solver = z3.Solver()
        solver.add(formula)
        return solver.check() == z3.sat

    def step_is_feasible(self, src, dst, trans_rel):
        """Is ``trans_rel`` satisfiable with ``src``/``dst`` plugged in?"""
        trans = _as_expr(trans_rel, self.state_vars + self.next_vars)
        return self._sat(z3.And(trans,
                                src.constraint(self.state_vars),
                                dst.constraint(self.next_vars)))

    def validate(self, cex, init_cond, trans_rel, safety):
        """Simulate ``cex`` concretely and report whether it is real.

        Returns a :class:`ValidationResult`.  ``first_spurious_step`` is the
        index of the first transition that cannot happen concretely, or ``-1``
        when the trace fails already in its initial state.
        """
        states = cex.states
        if not states:
            return ValidationResult(False, None, "empty trace")

        init = _as_expr(init_cond, self.state_vars)
        safe = _as_expr(safety, self.state_vars)

        # The trace has to start inside the initial condition.
        if not self._sat(z3.And(init, states[0].constraint(self.state_vars))):
            return ValidationResult(False, -1, "initial state violates init")

        # Every step has to be a concrete transition.
        for index, step in enumerate(cex.transitions):
            if not self.step_is_feasible(step.src, step.dst, trans_rel):
                return ValidationResult(False, index,
                                        "transition %d is infeasible" % index)

        # And the last state has to break the property.
        last = states[-1].constraint(self.state_vars)
        if not self._sat(z3.And(z3.Not(safe), last)):
            return ValidationResult(False, len(cex.transitions),
                                    "final state does not violate safety")

        return ValidationResult(True, None, "concrete trace reaches the error")


# ---------------------------------------------------------------------------
# 3. Predicate abstraction domain
# ---------------------------------------------------------------------------

class AbstractDomain(object):
    """The set of predicates the abstraction currently tracks.

    Predicates are formulas over ``state_vars``.  The abstract state of a
    concrete state is the vector of truth values of those predicates.
    """

    def __init__(self, state_vars, predicates=None, pinned=None):
        self.state_vars = list(state_vars)
        self._predicates = []
        self._pinned = set()
        for pred in (pinned or []):
            self.add_predicate(pred, pin=True)
        for pred in (predicates or []):
            self.add_predicate(pred)

    # -- inspection ---------------------------------------------------------

    @property
    def predicates(self):
        return list(self._predicates)

    @property
    def predicate_count(self):
        return len(self._predicates)

    def __len__(self):
        return len(self._predicates)

    def __iter__(self):
        return iter(self._predicates)

    def is_pinned(self, pred):
        return str(pred) in self._pinned

    # -- semantic tests -----------------------------------------------------

    @staticmethod
    def _valid(formula):
        solver = z3.Solver()
        solver.add(z3.Not(formula))
        return solver.check() == z3.unsat

    def is_subsumed(self, pred_new, pred_existing):
        """True when ``pred_existing`` implies ``pred_new``.

        A predicate implied by one we already track carries no extra
        information as a *conjunct*, which is how :meth:`add_predicate` and
        :meth:`PredicateRefiner.strengthen_invariant` use it.
        """
        return self._valid(z3.Implies(pred_existing, pred_new))

    def is_trivial(self, pred):
        """True for predicates that are valid or unsatisfiable."""
        solver = z3.Solver()
        solver.add(pred)
        if solver.check() == z3.unsat:
            return True
        return self._valid(pred)

    # -- mutation -----------------------------------------------------------

    def add_predicate(self, pred, pin=False):
        """Add ``pred`` unless it is trivial or already subsumed.

        Any *non-pinned* predicate that ``pred`` subsumes is dropped again.
        Predicates coming from the property under verification are pinned:
        they are implied by many refinement predicates, and removing them would
        coarsen the abstraction below the property itself and make the loop
        diverge.
        """
        pred = z3.simplify(pred)
        if not z3.is_expr(pred) or pred.sort() != z3.BoolSort():
            return False
        if self.is_trivial(pred):
            return False
        for existing in self._predicates:
            if str(existing) == str(pred):
                if pin:
                    self._pinned.add(str(existing))
                return False
            if self.is_subsumed(pred, existing):
                return False
        kept = []
        for existing in self._predicates:
            if not self.is_pinned(existing) and self.is_subsumed(existing, pred):
                continue
            kept.append(existing)
        kept.append(pred)
        self._predicates = kept
        if pin:
            self._pinned.add(str(pred))
        return True

    def extend(self, preds, pin=False):
        """Add several predicates, returning how many were actually kept."""
        return sum(1 for p in preds if self.add_predicate(p, pin=pin))

    # -- abstraction --------------------------------------------------------

    def abstract_state(self, concrete_state):
        """Evaluate every predicate on ``concrete_state``.

        ``concrete_state`` may be a :class:`State` or a plain ``dict``; the
        result is a tuple of booleans, one per predicate.
        """
        if not isinstance(concrete_state, State):
            concrete_state = State(concrete_state)
        binding = concrete_state.constraint(self.state_vars)
        out = []
        for pred in self._predicates:
            value = z3.simplify(z3.substitute(
                pred, *[(v, _z3_value(concrete_state[v.decl().name()], v.sort()))
                        for v in self.state_vars
                        if v.decl().name() in concrete_state.values]))
            if z3.is_true(value):
                out.append(True)
            elif z3.is_false(value):
                out.append(False)
            else:  # partially specified state: fall back to an SMT check
                solver = z3.Solver()
                solver.add(z3.And(binding, z3.Not(pred)))
                out.append(solver.check() == z3.unsat)
        return tuple(out)

    def cube(self, valuation, variables=None):
        """The concrete formula described by an abstract state."""
        variables = variables or self.state_vars
        parts = []
        for pred, value in zip(self._predicates, valuation):
            renamed = _substitute(pred, self.state_vars, variables)
            parts.append(renamed if value else z3.Not(renamed))
        return _conj(parts)


# ---------------------------------------------------------------------------
# 4. Interpolation-based predicate refinement
# ---------------------------------------------------------------------------

class PredicateRefiner(object):
    """Derives new predicates from an infeasible counterexample.

    The workhorse is :meth:`interpolate`, a model-based Craig interpolation
    procedure: it repeatedly samples a model of the prefix ``A``, turns it into
    a cube over the shared variables, weakens the cube as far as it stays
    inconsistent with the suffix ``B``, and blocks it.  When ``A`` is exhausted
    the disjunction of the collected cubes ``I`` satisfies ``A |= I`` and
    ``I /\\ B`` unsat, i.e. it is an interpolant.
    """

    def __init__(self, state_vars, next_vars, atom_basis=None, max_cubes=6,
                 use_octagons=True):
        self.state_vars = list(state_vars)
        self.next_vars = list(next_vars)
        self.atom_basis = list(atom_basis or [])
        self.max_cubes = max_cubes
        self.use_octagons = use_octagons

    # -- path construction --------------------------------------------------

    def _path_vars(self, steps):
        """Fresh copies ``X^0 .. X^steps`` of the state variables."""
        return [_rename("s%d_" % i, self.state_vars) for i in range(steps + 1)]

    def path_formula(self, cex, trans_rel, init_cond=None, safety=None,
                     cubes=None):
        """Unroll the trace into ``(parts, path_vars)``.

        ``parts[0]`` constrains the first state, ``parts[i]`` is the ``i``-th
        transition (plus the abstract cube of the state it reaches) and the last
        part demands the safety violation.  Without ``init_cond``/``safety`` the
        trace's own end states are used as anchors, which asks the question
        "can exactly this trace happen?".
        """
        steps = cex.length if isinstance(cex, Counterexample) else int(cex)
        path = self._path_vars(steps)
        states = cex.states if isinstance(cex, Counterexample) else []

        def cube_at(index, variables):
            if not cubes:
                return None
            return _substitute(cubes[index], self.state_vars, variables)

        head = []
        if init_cond is not None:
            head.append(_substitute(_as_expr(init_cond, self.state_vars),
                                    self.state_vars, path[0]))
        elif states:
            head.append(states[0].constraint(path[0]))
        head.append(cube_at(0, path[0]))
        parts = [_conj(head)]

        trans = _as_expr(trans_rel, self.state_vars + self.next_vars)
        for i in range(steps):
            step = z3.substitute(
                trans,
                *([(v, n) for v, n in zip(self.state_vars, path[i])] +
                  [(v, n) for v, n in zip(self.next_vars, path[i + 1])]))
            parts.append(_conj([step, cube_at(i + 1, path[i + 1])]))

        tail = []
        if safety is not None:
            tail.append(z3.Not(_substitute(_as_expr(safety, self.state_vars),
                                           self.state_vars, path[steps])))
        elif states:
            tail.append(states[steps].constraint(path[steps]))
        parts.append(_conj(tail))
        return parts, path

    def path_is_feasible(self, cex, trans_rel, init_cond=None, safety=None,
                         cubes=None):
        """Check whether some concrete run follows the given path.

        Returns ``(feasible, states)`` where ``states`` is the concrete trace
        read from the model when the path is feasible.
        """
        parts, path = self.path_formula(cex, trans_rel, init_cond, safety, cubes)
        solver = z3.Solver()
        solver.add(_conj(parts))
        if solver.check() != z3.sat:
            return False, None
        model = solver.model()
        names = [v.decl().name() for v in self.state_vars]
        return True, [State.from_model(model, step_vars, names)
                      for step_vars in path]

    # -- interpolation ------------------------------------------------------

    def _basis_for(self, formulas, shared_vars):
        """Atoms over ``shared_vars`` gathered from ``formulas`` and the basis."""
        atoms = []
        for formula in formulas:
            collect_atoms(formula, atoms)
        for atom in self.atom_basis:
            for variables in (shared_vars,):
                renamed = _substitute(atom, self.state_vars, variables)
                if all(str(renamed) != str(a) for a in atoms):
                    atoms.append(renamed)
        return [a for a in atoms if _mentions_only(a, shared_vars)]

    def _model_cube(self, model, shared_vars, atoms):
        """A cube over ``shared_vars`` satisfied by ``model``.

        Literals are ordered from most to least specific so that the greedy
        weakening below drops point values first and keeps relational facts.
        """
        numeric = [v for v in shared_vars
                   if v.sort() in (z3.IntSort(), z3.RealSort())]
        bounds, sums, diffs, syntactic = [], [], [], []

        for var in shared_vars:
            value = model.eval(var, model_completion=True)
            if var.sort() == z3.BoolSort():
                syntactic.append(var if z3.is_true(value) else z3.Not(var))
            elif var in numeric:
                bounds.append(var <= value)
                bounds.append(var >= value)

        if self.use_octagons:
            for left, right in itertools.combinations(numeric, 2):
                total = model.eval(left + right, model_completion=True)
                delta = model.eval(left - right, model_completion=True)
                sums.append(left + right <= total)
                sums.append(left + right >= total)
                diffs.append(left - right <= delta)
                diffs.append(left - right >= delta)

        for atom in atoms:
            if atom.sort() != z3.BoolSort():
                continue
            value = model.eval(atom, model_completion=True)
            if z3.is_true(value):
                syntactic.append(atom)
            elif z3.is_false(value):
                syntactic.append(z3.Not(atom))

        return bounds + sums + diffs + syntactic

    def _weaken(self, literals, suffix):
        """Drop literals while the cube stays inconsistent with ``suffix``."""
        solver = z3.Solver()
        solver.add(suffix)

        def blocked(lits):
            solver.push()
            solver.add(*lits) if lits else None
            result = solver.check()
            solver.pop()
            return result == z3.unsat

        if not blocked(literals):
            return None  # the atom basis cannot separate this model
        kept = list(literals)
        index = 0
        while index < len(kept):
            trial = kept[:index] + kept[index + 1:]
            if blocked(trial):
                kept = trial
            else:
                index += 1
        return kept

    def interpolate(self, prefix, suffix, shared_vars):
        """Craig interpolant of ``prefix`` and ``suffix`` over ``shared_vars``.

        Returns a formula ``I`` with ``prefix |= I`` and ``I /\\ suffix``
        unsatisfiable, or ``None`` when ``prefix /\\ suffix`` is satisfiable or
        the atom basis is too weak to separate them.
        """
        joint = z3.Solver()
        joint.add(prefix, suffix)
        if joint.check() != z3.unsat:
            return None

        atoms = self._basis_for([prefix, suffix], shared_vars)
        sampler = z3.Solver()
        sampler.add(prefix)
        cubes = []
        for _ in range(self.max_cubes):
            if sampler.check() != z3.sat:
                if not cubes:
                    return z3.BoolVal(False)
                return z3.simplify(z3.Or(*cubes) if len(cubes) > 1 else cubes[0])
            literals = self._model_cube(sampler.model(), shared_vars, atoms)
            kept = self._weaken(literals, suffix)
            if kept is None:
                return None
            cube = _conj(kept)
            cubes.append(cube)
            sampler.add(z3.Not(cube))
        return None

    def extract_interpolants(self, cex, trans_rel, init_cond=None, safety=None,
                             cubes=None):
        """Interpolate between consecutive steps of an infeasible trace.

        For every cut point ``j`` the path is split into the prefix (steps
        ``0..j``) and the suffix (steps ``j+1..n`` together with the safety
        violation).  ``prefix /\\ ~suffix`` unsatisfiable means the trace cannot
        pass through step ``j``, and the interpolant -- a formula over the state
        at step ``j`` only -- is renamed back onto the state variables and
        returned as a new predicate.
        """
        parts, path = self.path_formula(cex, trans_rel, init_cond, safety, cubes)
        interpolants = []
        for cut in range(1, len(parts) - 1):
            prefix = _conj(parts[:cut + 1])
            suffix = _conj(parts[cut + 1:])
            interpolant = self.interpolate(prefix, suffix, path[cut])
            if interpolant is None:
                continue
            interpolant = _substitute(interpolant, path[cut], self.state_vars)
            if z3.is_true(interpolant) or z3.is_false(interpolant):
                continue
            interpolants.append(z3.simplify(interpolant))
        return interpolants

    @staticmethod
    def split_predicates(formula):
        """Break a formula into the atoms a predicate abstraction can track."""
        out = []
        for atom in collect_atoms(formula):
            if all(str(atom) != str(o) for o in out):
                out.append(atom)
        if not out and z3.is_expr(formula):
            out.append(formula)
        return out

    def strengthen_invariant(self, current_preds, new_interpolants):
        """Merge interpolants into a predicate set, dropping subsumed ones.

        The result is ordered ``current_preds`` first; a new predicate is only
        kept when no predicate already in the set implies it, and predicates it
        implies are removed (the conjunction of the set is unchanged by both
        rules).
        """
        domain = AbstractDomain(self.state_vars)
        for pred in current_preds:
            domain.add_predicate(pred, pin=True)
        for interpolant in new_interpolants:
            for pred in self.split_predicates(interpolant):
                domain.add_predicate(pred)
        return domain.predicates

    # -- minimization -------------------------------------------------------

    def minimize_cex(self, cex, trans_rel):
        """Shorten a trace by jumping over intermediate states.

        Whenever ``trans_rel`` admits a direct step from state ``i`` to a later
        state ``j``, everything in between is redundant: the shortened trace
        starts in the same state, ends in the same (error) state and uses only
        real transitions.  Longer jumps are tried first, and the scan is
        repeated until no jump is left.
        """
        if cex is None or cex.length <= 1:
            return cex
        validator = CEXValidator(self.state_vars, self.next_vars)
        states = list(cex.states)
        actions = [t.action for t in cex.transitions]

        index = 0
        while index < len(states) - 2:
            jumped = False
            for target in range(len(states) - 1, index + 1, -1):
                if validator.step_is_feasible(states[index], states[target],
                                              trans_rel):
                    states = states[:index + 1] + states[target:]
                    actions = (actions[:index] + ["jump"] + actions[target:])
                    jumped = True
                    break
            if not jumped:
                index += 1
        return Counterexample.from_states(states, actions)


# ---------------------------------------------------------------------------
# 5. The CEGAR loop
# ---------------------------------------------------------------------------

class CEGARResult(object):
    """Outcome of :meth:`CEGARLoop.run`."""

    def __init__(self, safe, iterations, predicates, cex=None, status=None,
                 original_cex=None, interpolants=None, predicates_added=0,
                 validations=None, elapsed=0.0, name=None):
        self.safe = safe
        self.iterations = iterations
        self.predicates = list(predicates or [])
        self.cex = cex
        self.status = status or ("safe" if safe else "unsafe")
        self.original_cex = original_cex
        self.interpolants = list(interpolants or [])
        self.predicates_added = predicates_added
        self.validations = list(validations or [])
        self.elapsed = elapsed
        self.name = name

    @property
    def predicate_count(self):
        return len(self.predicates)

    @property
    def cex_length(self):
        return self.cex.length if self.cex is not None else 0

    @property
    def original_cex_length(self):
        cex = self.original_cex if self.original_cex is not None else self.cex
        return cex.length if cex is not None else 0

    def __repr__(self):
        return ("CEGARResult(name=%s, safe=%s, status=%s, iterations=%d, "
                "predicates=%d, cex_length=%s)" % (
                    self.name, self.safe, self.status, self.iterations,
                    len(self.predicates), self.cex_length))


class CEGARLoop(object):
    """Counterexample-guided abstraction refinement over a transition system.

    ``init_cond``, ``trans_rel`` and ``safety`` are either Z3 formulas over
    ``state_vars``/``next_vars`` or callables that build them from those
    variables.  When the variables are not given explicitly they are inferred:
    the constants of ``init_cond`` and ``safety`` are the state variables and
    the remaining constants of ``trans_rel`` are their primed copies (matched by
    the ``_next``/``'``/``p`` naming conventions used across this repository).
    """

    NEXT_SUFFIXES = ("_next", "_p", "'", "p", "n", "!1", "_1")

    def __init__(self, init_cond, trans_rel, safety, max_iterations=20,
                 predicate_budget=50, state_vars=None, next_vars=None,
                 name="system", seed_predicates=None, max_trace_depth=12,
                 timeout_ms=None):
        self.name = name
        self.max_iterations = max_iterations
        self.predicate_budget = predicate_budget
        self.max_trace_depth = max_trace_depth
        self.timeout_ms = timeout_ms

        state_vars, next_vars = self._infer_variables(
            init_cond, trans_rel, safety, state_vars, next_vars)
        self.state_vars = state_vars
        self.next_vars = next_vars

        self.init_cond = _as_expr(init_cond, state_vars)
        self.trans_rel = _as_expr(trans_rel, state_vars + next_vars)
        self.safety = _as_expr(safety, state_vars)

        atom_basis = self._program_atoms()
        self.refiner = PredicateRefiner(state_vars, next_vars,
                                        atom_basis=atom_basis)
        self.validator = CEXValidator(state_vars, next_vars)

        # The property atoms are seeded (and pinned) first so that the very
        # first abstraction can already talk about the safety property.
        self.domain = AbstractDomain(state_vars)
        seeds = list(seed_predicates) if seed_predicates is not None else (
            collect_atoms(self.safety) + collect_atoms(self.init_cond))
        self.seed_predicates = seeds
        self.domain.extend(seeds, pin=True)

        self.iterations = 0
        self.predicates_added = 0
        self.interpolants = []
        self.validations = []
        self.traces = []

    # -- setup --------------------------------------------------------------

    def _infer_variables(self, init_cond, trans_rel, safety, state_vars,
                         next_vars):
        if state_vars is not None and next_vars is not None:
            return list(state_vars), list(next_vars)
        if state_vars is None:
            if callable(init_cond) and not z3.is_expr(init_cond):
                raise ValueError("state_vars is required for callable systems")
            state_vars = collect_vars(init_cond)
            collect_vars(_as_expr(safety, state_vars), state_vars)
        state_vars = list(state_vars)
        if next_vars is None:
            trans = _as_expr(trans_rel, state_vars)
            known = set(str(v) for v in state_vars)
            leftovers = [v for v in collect_vars(trans) if str(v) not in known]
            next_vars = []
            for var in state_vars:
                base = var.decl().name()
                match = None
                for candidate in leftovers:
                    name = candidate.decl().name()
                    if any(name == base + suffix for suffix in self.NEXT_SUFFIXES):
                        match = candidate
                        break
                if match is None:
                    match = z3.Const(base + "_next", var.sort())
                next_vars.append(match)
        return state_vars, list(next_vars)

    def _program_atoms(self):
        """Atoms of the program, expressed over the unprimed state variables."""
        atoms = collect_atoms(self.init_cond)
        collect_atoms(self.safety, atoms)
        for atom in collect_atoms(self.trans_rel):
            unprimed = _substitute(atom, self.next_vars, self.state_vars)
            if all(str(unprimed) != str(a) for a in atoms):
                atoms.append(unprimed)
        return [a for a in atoms if _mentions_only(a, self.state_vars)]

    # -- abstraction --------------------------------------------------------

    def _link(self, bits, variables):
        """``b_i <-> p_i(variables)`` for every tracked predicate."""
        predicates = self.domain.predicates
        parts = [bits[i] == _substitute(predicates[i], self.state_vars, variables)
                 for i in range(len(predicates))]
        return _conj(parts)

    def abstract_query(self):
        """Ask Spacer whether the current abstraction can reach the error.

        Returns ``(result, abstract_trace)``; the trace is the list of abstract
        states (tuples of booleans) extracted from Spacer's ground refutation.
        """
        predicates = self.domain.predicates
        arity = len(predicates)
        fp = z3.Fixedpoint()
        fp.set(engine="spacer")
        if self.timeout_ms:
            fp.set(timeout=int(self.timeout_ms))

        inv = z3.Function("Inv", *([z3.BoolSort()] * arity + [z3.BoolSort()]))
        error = z3.Function("Error_%s" % self.name.replace(" ", "_"),
                            z3.BoolSort())
        fp.register_relation(inv, error)

        bits = [z3.Bool("b%d" % i) for i in range(arity)]
        next_bits = [z3.Bool("b%d_next" % i) for i in range(arity)]
        fp.declare_var(*(bits + next_bits + self.state_vars + self.next_vars))

        fp.rule(inv(*bits), [self.init_cond, self._link(bits, self.state_vars)],
                "init")
        fp.rule(inv(*next_bits),
                [inv(*bits), self._link(bits, self.state_vars), self.trans_rel,
                 self._link(next_bits, self.next_vars)], "step")
        fp.rule(error(), [inv(*bits), self._link(bits, self.state_vars),
                          z3.Not(self.safety)], "error")

        result = fp.query(error())
        trace = None
        if result == z3.sat:
            try:
                trace = self._extract_abstract_trace(fp.get_answer(), arity)
            except z3.Z3Exception:  # pragma: no cover - defensive
                trace = None
        return result, trace

    @staticmethod
    def _extract_abstract_trace(answer, arity):
        """Read the ground ``Inv(...)`` facts out of a Spacer refutation.

        Spacer answers a ``sat`` query with a hyper-resolution proof whose
        intermediate conclusions are the ground facts of the derivation, i.e.
        exactly the abstract states along the counterexample.  They appear
        outermost-first, so the collected list is reversed.
        """
        facts = []

        def walk(expr):
            if not z3.is_app(expr):
                return
            if expr.num_args():
                conclusion = expr.arg(expr.num_args() - 1)
                if z3.is_app(conclusion) and conclusion.decl().name() == "Inv":
                    valuation = tuple(z3.is_true(conclusion.arg(i))
                                      for i in range(conclusion.num_args()))
                    if all(z3.is_true(conclusion.arg(i)) or
                           z3.is_false(conclusion.arg(i))
                           for i in range(conclusion.num_args())):
                        facts.append(valuation)
            for i in range(expr.num_args()):
                walk(expr.arg(i))

        walk(answer)
        if not facts and arity == 0:
            return [()]
        seen_last = None
        ordered = []
        for fact in reversed(facts):
            ordered.append(fact)
            seen_last = fact
        del seen_last
        return ordered

    def _concretize(self, abstract_trace):
        """Pick one concrete witness per abstract state of the trace.

        Each witness satisfies the predicates of its abstract state (and the
        initial condition / safety violation at the ends), but consecutive
        witnesses are chosen independently -- which is precisely why the result
        is only a *candidate* counterexample that has to be validated.
        """
        states = []
        last = len(abstract_trace) - 1
        for index, valuation in enumerate(abstract_trace):
            solver = z3.Solver()
            solver.add(self.domain.cube(valuation))
            if index == 0:
                solver.add(self.init_cond)
            if index == last:
                solver.add(z3.Not(self.safety))
            if solver.check() != z3.sat:
                solver = z3.Solver()
                solver.add(self.domain.cube(valuation))
                if solver.check() != z3.sat:
                    return None
            states.append(State.from_model(solver.model(), self.state_vars))
        return Counterexample.from_states(states)

    # -- main loop ----------------------------------------------------------

    def run(self):
        """Run the CEGAR loop and return a :class:`CEGARResult`."""
        started = time.time()
        status = "max_iterations"
        while self.iterations < self.max_iterations:
            self.iterations += 1
            result, abstract_trace = self.abstract_query()

            if result == z3.unsat:
                return self._result(True, "safe", started)
            if result != z3.sat:
                status = "unknown"
                break
            if not abstract_trace:
                status = "no_trace"
                break

            self.traces.append(abstract_trace)
            cubes = [self.domain.cube(v) for v in abstract_trace]
            candidate = self._concretize(abstract_trace)
            if candidate is None:  # pragma: no cover - defensive
                status = "no_trace"
                break

            verdict = self.validator.validate(candidate, self.init_cond,
                                              self.trans_rel, self.safety)
            self.validations.append(verdict)
            if verdict.is_real:
                return self._unsafe(candidate, started)

            # The candidate is spurious; is *any* run along this abstract path
            # concrete?  If so the system really is unsafe.
            feasible, concrete = self.refiner.path_is_feasible(
                candidate, self.trans_rel, self.init_cond, self.safety, cubes)
            if feasible:
                return self._unsafe(Counterexample.from_states(concrete), started)

            interpolants = self.refiner.extract_interpolants(
                candidate, self.trans_rel, self.init_cond, self.safety, cubes)
            self.interpolants.extend(interpolants)
            added = 0
            for interpolant in interpolants:
                for pred in self.refiner.split_predicates(interpolant):
                    if self.domain.add_predicate(pred):
                        added += 1
            if added == 0:
                status = "no_refinement"
                break
            self.predicates_added += added
            if self.domain.predicate_count > self.predicate_budget:
                status = "predicate_budget_exceeded"
                break

        return self._result(False, status, started)

    def _unsafe(self, cex, started):
        minimized = self.refiner.minimize_cex(cex, self.trans_rel)
        return self._result(False, "unsafe", started, cex=minimized,
                            original_cex=cex)

    def _result(self, safe, status, started, cex=None, original_cex=None):
        return CEGARResult(
            safe=safe,
            iterations=self.iterations,
            predicates=self.domain.predicates,
            cex=cex,
            status=status,
            original_cex=original_cex,
            interpolants=self.interpolants,
            predicates_added=self.predicates_added,
            validations=self.validations,
            elapsed=time.time() - started,
            name=self.name,
        )


# ---------------------------------------------------------------------------
# 6. Benchmark systems and the experiment driver
# ---------------------------------------------------------------------------

class CEGARSystem(object):
    """A named transition system together with its expected CEGAR verdict."""

    def __init__(self, name, state_vars, next_vars, init, trans, safety,
                 description="", expected_safe=None):
        self.name = name
        self.state_vars = list(state_vars)
        self.next_vars = list(next_vars)
        self.init = init
        self.trans = trans
        self.safety = safety
        self.description = description
        self.expected_safe = expected_safe

    def loop(self, **kwargs):
        kwargs.setdefault("name", self.name)
        return CEGARLoop(self.init, self.trans, self.safety,
                         state_vars=self.state_vars,
                         next_vars=self.next_vars, **kwargs)

    def __repr__(self):
        return "CEGARSystem(%s)" % self.name


def _vars(names):
    """``(state_vars, next_vars)`` integer variables for ``names``."""
    state = [z3.Int(n) for n in names]
    nxt = [z3.Int(n + "_next") for n in names]
    return state, nxt


def build_offbyone_counter(bound=10):
    """Counter whose companion variable trails it by one.

    ``y`` is always ``x + 1``, so with ``x <= bound`` the bound ``y <= bound+1``
    holds -- but neither conjunct is inductive on its own, so the abstraction
    has to discover the relational invariant ``y - x <= 1`` first.
    """
    state, nxt = _vars(["x", "y"])
    x, y = state
    xn, yn = nxt
    init = z3.And(x == 0, y == 1)
    trans = z3.Or(z3.And(x < bound, xn == x + 1, yn == y + 1),
                  z3.And(x >= bound, xn == x, yn == y))
    safety = y <= bound + 1
    return CEGARSystem("offbyone_counter", state, nxt, init, trans, safety,
                       "counter with an off-by-one companion variable",
                       expected_safe=True)


def build_double_counter(limit=6):
    """``x += 1`` / ``y += 2`` each step; ``x + y <= limit`` really is violated."""
    state, nxt = _vars(["x", "y"])
    x, y = state
    xn, yn = nxt
    init = z3.And(x == 0, y == 0)
    trans = z3.And(xn == x + 1, yn == y + 2)
    safety = x + y <= limit
    return CEGARSystem("double_counter", state, nxt, init, trans, safety,
                       "double counter that overruns its budget",
                       expected_safe=False)


def build_array_bounds(size=8):
    """Index/length/counter walk of an array; the index stays in bounds.

    Three separate facts are needed -- ``len`` never changes, ``idx <= len`` and
    ``cnt`` follows ``idx`` -- so the abstraction is refined several times.
    """
    state, nxt = _vars(["idx", "cnt", "len"])
    idx, cnt, length = state
    idxn, cntn, lengthn = nxt
    init = z3.And(idx == 0, cnt == 0, length == size)
    step = z3.And(idx < length, idxn == idx + 1, cntn == cnt + 1,
                  lengthn == length)
    done = z3.And(idx >= length, idxn == idx, cntn == cnt, lengthn == length)
    trans = z3.Or(step, done)
    safety = z3.And(idx >= 0, idx <= length, cnt <= size)
    return CEGARSystem("array_bounds", state, nxt, init, trans, safety,
                       "array index/counter stays inside the array",
                       expected_safe=True)


def build_simple_loop():
    """``x := x + 1`` from zero; ``x >= 0`` is inductive, so no refinement."""
    state, nxt = _vars(["x"])
    x = state[0]
    xn = nxt[0]
    init = x == 0
    trans = xn == x + 1
    safety = x >= 0
    return CEGARSystem("simple_loop", state, nxt, init, trans, safety,
                       "increment loop with the inductive invariant x >= 0",
                       expected_safe=True)


def build_producer_consumer(capacity=3):
    """Producer/consumer over a bounded buffer that can overflow.

    ``produce``, ``consume`` and ``idle`` are all enabled, so the error is
    reachable by many traces of different lengths -- the ones with idle or
    produce/consume detours are exactly what :meth:`minimize_cex` removes.
    """
    state, nxt = _vars(["buf", "prod", "cons"])
    buf, prod, cons = state
    bufn, prodn, consn = nxt
    init = z3.And(buf == 0, prod == 0, cons == 0)
    produce = z3.And(bufn == buf + 1, prodn == prod + 1, consn == cons)
    consume = z3.And(buf > 0, bufn == buf - 1, consn == cons + 1, prodn == prod)
    idle = z3.And(bufn == buf, prodn == prod, consn == cons)
    trans = z3.Or(produce, consume, idle)
    safety = buf <= capacity
    return CEGARSystem("producer_consumer", state, nxt, init, trans, safety,
                       "bounded buffer that overflows its capacity",
                       expected_safe=False)


SYSTEM_BUILDERS = [
    build_offbyone_counter,
    build_double_counter,
    build_array_bounds,
    build_simple_loop,
    build_producer_consumer,
]

METRICS = [
    "CEGAR_ITERATIONS",
    "CEGAR_PREDICATES_ADDED",
    "CEGAR_CEX_LENGTH_ORIGINAL",
    "CEGAR_CEX_LENGTH_MINIMIZED",
    "CEGAR_VERIFIED_SAFE",
]


class CEXMinimizerExperiment(object):
    """Run the CEGAR loop over the benchmark systems and collect the metrics."""

    def __init__(self, systems=None, max_iterations=20, predicate_budget=50):
        self.systems = list(systems) if systems is not None else [
            builder() for builder in SYSTEM_BUILDERS]
        self.max_iterations = max_iterations
        self.predicate_budget = predicate_budget
        self.results = []

    def run(self):
        """Verify every system, returning the metric dictionary."""
        self.results = []
        for system in self.systems:
            loop = system.loop(max_iterations=self.max_iterations,
                               predicate_budget=self.predicate_budget)
            self.results.append(loop.run())
        return self.metrics()

    def metrics(self):
        unsafe = [r for r in self.results if r.cex is not None]
        metrics = {
            "CEGAR_ITERATIONS": sum(r.iterations for r in self.results),
            "CEGAR_PREDICATES_ADDED": sum(r.predicates_added
                                          for r in self.results),
            "CEGAR_CEX_LENGTH_ORIGINAL": sum(r.original_cex_length
                                             for r in unsafe),
            "CEGAR_CEX_LENGTH_MINIMIZED": sum(r.cex_length for r in unsafe),
            "CEGAR_VERIFIED_SAFE": sum(1 for r in self.results if r.safe),
        }
        return metrics

    def summary(self):
        """Human-readable per-system report (used by the tests and CLI)."""
        lines = []
        for result in self.results:
            lines.append("%-20s %-8s iterations=%2d predicates=%2d "
                         "cex=%s->%s" % (
                             result.name, result.status, result.iterations,
                             len(result.predicates),
                             result.original_cex_length, result.cex_length))
        return "\n".join(lines)


def run_cegar_experiments(systems=None):
