def _relaxations(self, literal):
    """Weaker versions of a ``term <= c`` / ``term >= c`` literal.

    The replacement bounds are the constants of the program, tried from the
    weakest one down.  Relaxing a model-derived bound such as
    ``cnt - len <= -7`` into the program bound ``cnt - len <= 0`` is what
    turns a snapshot of one state into a candidate invariant.
    """
    if not z3.is_app(literal) or literal.num_args() != 2:
        return []
    bound = literal.arg(1)
    if not z3.is_int_value(bound):
        return []
    term, value = literal.arg(0), bound.as_long()
    if z3.is_le(literal):
        return [term <= c for c in sorted(self.constants, reverse=True)
                if c > value]
    if z3.is_ge(literal):
        return [term >= c for c in sorted(self.constants) if c < value]
    return []

def _weaken(self, literals, suffix):
    """Drop and relax literals while the cube stays inconsistent with ``suffix``."""
    solver = z3.Solver()
    solver.add(suffix)

    def blocked(lits):
        solver.push()
        for lit in lits:
            solver.add(lit)
        result = solver.check()
        solver.pop()
        return result == z3.unsat

    if not blocked(literals):
        return None  # the atom basis cannot separate this model
    kept = list(literals)
    for _ in range(2):
        index = 0
        while index < len(kept):
            trial = kept[:index] + kept[index + 1:]
            if blocked(trial):
                kept = trial
            else:
                index += 1
        relaxed = False
        for index, literal in enumerate(kept):
            for candidate in self._relaxations(literal):
                trial = kept[:index] + [candidate] + kept[index + 1:]
                if blocked(trial):
                    kept = trial
                    relaxed = True
                    break
        if not relaxed:
            break
    return kept

