def _prefer_program_constants(self, literals):
    """Order literals so model-specific bounds are weakened away first.

    ``cnt - len <= -7`` only describes the sampled state, while
    ``cnt - idx <= 0`` mentions a constant the program itself uses and is a
    far better invariant candidate, so the former is offered for removal
    before the latter.
    """
    pool = set(self.constants)
    return sorted(literals,
                  key=lambda lit: 1 if self._bound_constant(lit) in pool
                  else 0)

