def _model_cube(self, model, shared_vars, atoms):
    """A cube over ``shared_vars`` satisfied by ``model``.

    Literals are ordered from most to least specific so that the greedy
    weakening below drops point values first and keeps relational facts.
    """
    numeric = [v for v in shared_vars
               if v.sort() in (z3.IntSort(), z3.RealSort())]
    bounds, sums, diffs, syntactic = [], [], [], []

    for var in shared_vars:
        value = model.eval(var, model_completion=True)
        if var.sort() == z3.BoolSort():
            syntactic.append(var if z3.is_true(value) else z3.Not(var))
        elif var in numeric:
            bounds.append(var <= value)
            bounds.append(var >= value)

