        if z3.is_true(value):
            syntactic.append(atom)
        elif z3.is_false(value):
            syntactic.append(z3.Not(atom))

    return (self._prefer_program_constants(bounds)
            + self._prefer_program_constants(sums)
            + self._prefer_program_constants(diffs)
            + syntactic)

