def concrete_witness(self, depth=None):
    """Look for a real error trace of the concrete system.

    The horizon ``depth`` is unrolled in one go, exactly like a bounded
    model checker: the answer is *a* trace that reaches the error inside the
    horizon, not the shortest one.  Systems that can idle or undo their work
    happily pad such a trace out to the full horizon, which is what makes
    :meth:`PredicateRefiner.minimize_cex` worth running afterwards.  When
    the horizon itself is infeasible (the system may deadlock or run past
    the error), shorter unrollings are tried in turn.
    """
    depth = self.max_trace_depth if depth is None else depth
    for steps in [depth] + list(range(depth - 1, -1, -1)):
        feasible, states = self.refiner.path_is_feasible(
            steps, self.trans_rel, self.init_cond, self.safety)
        if feasible:
            return Counterexample.from_states(states)
    return None

